\begin{theorem}\label{thm:main orientable}
Every compact, connected orientable Riemannian isometric filling \(M\) of a circle of length \(2\pi\) satisfies
\[
\operatorname{Area}(M)>5.40154.
\]   
\end{theorem}

\begin{theorem}\label{thm:nonlinear-formula}
Let $M$ be a compact connected orientable Riemannian isometric filling of $\T$. For every $0\leq\lambda<\pi^2/32$, we have
\begin{equation}\label{eq:nonlinear-master}
\operatorname{Area}(M)\geq
\frac{C_0+b\lambda+d\lambda^2}
{1+\lambda^2\left[
Q_*+\dfrac{C_*^2}{4(1-D_*\lambda)}
\right]}.
\end{equation}
In particular,
$$\operatorname{Area}(M)>5.40154.$$
\end{theorem}

\begin{proposition}\label{prop:nonlinear-boundary-action}
For every $\lambda\geq0$, we have
\begin{equation}\label{eq:nonlinear-boundary-action}
\int_M\Omega_\lambda
=B(\lambda)
:=\pi\sum_{n\in\mathcal O}
n\left(\rho_n+\lambda\rho_1^2\rho_{n+2}\right)^2
=C_0+b\lambda+d\lambda^2.
\end{equation}
In particular, $b>0$.
\end{proposition}

\begin{lemma}\label{lem:nonlinear-first-variation}
Writing $a=z_1$ and $y_n=z_{n+2}$, we have
\begin{equation}\label{eq:nonlinear-first-variation}
\begin{aligned}
L={}&2\operatorname{Re}\left[a^2\sum_{n\in\mathcal O}\left(\overline{c_n}c_{n+2}-c_{-n}\overline{c_{-(n+2)}}\right)\right]\\
&+4\operatorname{Re}\left[a\sum_{n\in\mathcal O}\overline{y_n}
\left(c_{-1}\overline{c_n}-\overline{c_1}c_{-n}\right)\right].
\end{aligned}
\end{equation}
In particular, $L=0$ whenever $|\Omega_0|=1$.
\end{lemma}

\begin{proposition}\label{prop:nonlinear-linear-estimate}
At every common differentiability point and for every ordered orthonormal basis, set
$$\delta=1-|\Omega_0|.$$
Then
\begin{equation}\label{eq:nonlinear-linear-estimate}
|L|\leq C_*\sqrt\delta+D_*\delta.
\end{equation}
\end{proposition}

\begin{lemma}\label{lem:nonlinear-quadratic-estimate}
At every common differentiability point and for every ordered orthonormal basis, we have
$$ |Q|\leq Q_*.$$
\end{lemma}
